import type { ProviderId, ProviderPlanRequest } from "@/lib/providers";

function request(
  provider: ProviderId,
  capabilities: readonly string[],
  inputs: ProviderPlanRequest["inputs"],
  environment: ProviderPlanRequest["environment"] = "production",
): ProviderPlanRequest {
  return {
    environment,
    capabilities,
    credentialRef: `cred://${provider}/primary`,
    inputs,
    dryRun: true,
  };
}

